<?php
require_once __DIR__.'/../../config/cors.php';require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../helpers/response.php';require_once __DIR__.'/../../middleware/auth.php';
$actor=requireRole($pdo,['admin']);$format=strtolower((string)($_GET['format']??'csv'));if($format!=='csv')sendError('Only CSV export is supported.',422);$resource=$_GET['resource']??'calls';$allowed=['customers','leads','followups','bookings','calls','tasks'];if(!in_array($resource,$allowed,true))sendError('Unsupported report resource.',422);$tables=['followups'=>'follow_ups'];$columns=['customers'=>['id','name','phone','email','status','city','created_at'],'leads'=>['id','lead_code','name','phone','email','source','status','priority','assigned_to','created_at'],'followups'=>['id','lead_id','customer_id','assigned_to','scheduled_at','status','priority','channel'],'bookings'=>['id','booking_code','customer_id','lead_id','booking_date','status','payment_status','fare','driver_id','vehicle_id'],'calls'=>['id','lead_id','customer_id','executive_id','phone_number','call_type','call_status','duration_seconds','call_time','notes'],'tasks'=>['id','title','status','priority','assigned_to','start_date','due_date','created_at']];$cols=$columns[$resource];$from=isset($_GET['dateFrom'])?strtotime((string)$_GET['dateFrom']):false;$to=isset($_GET['dateTo'])?strtotime((string)$_GET['dateTo']):false;$dateCol=['customers'=>'created_at','leads'=>'created_at','followups'=>'scheduled_at','bookings'=>'booking_date','calls'=>'call_time','tasks'=>'due_date'][$resource];$where=[];$p=[];if($from!==false){$where[]="$dateCol >= :from";$p['from']=date('Y-m-d H:i:s',$from);}if($to!==false){$where[]="$dateCol <= :to";$p['to']=date('Y-m-d H:i:s',$to);}$table=$tables[$resource]??$resource;$sql='SELECT '.implode(',',$cols).' FROM `'.$table.'`';if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' ORDER BY '.$dateCol.' DESC';$s=$pdo->prepare($sql);$s->execute($p);$rows=$s->fetchAll(PDO::FETCH_ASSOC);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="cab-crm-'.$resource.'-'.date('Ymd-His').'.csv"');$out=fopen('php://output','w');fputcsv($out,$cols);foreach($rows as $row)fputcsv($out,$row);fclose($out);exit;
